/* FR-NAV1.30.67-HF3.13.49 — accepted local currentness projection and placeholder firewall. */
(()=>{'use strict';
const RELEASE='FR-NAV1.30.67-HF3.13.49';
const DATA='/data/r1367-currentness.json';
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
const lang=()=>document.documentElement.lang?.toLowerCase().startsWith('es')?'es':'en';
const pick=(v,l)=>v&&typeof v==='object'?(v[l]||v.en||''):String(v||'');
const localDay=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const isPlaceholder=card=>{const title=(q('h1,h2,h3,h4,strong',card)?.textContent||'').trim().toLowerCase();const text=(card.textContent||'').trim().toLowerCase();const state=String(card.dataset.currentnessState||card.dataset.eventState||'').toLowerCase();return title==='test'||state==='test'||state==='placeholder'||text.includes('test-only body');};
function placeholderFirewall(root=document){qa('.today-card,[data-currentness-item]',root).forEach(card=>{if(isPlaceholder(card))card.remove()});}
function card(item,l,heading='h3'){
 const a=document.createElement('article');a.className='r22-card today-card r24-event-card';a.dataset.eventCategory=item.category;a.dataset.eventStart=item.start;a.dataset.eventEnd=item.end;a.dataset.currentnessItem=item.id;
 const eyebrow=document.createElement('div');eyebrow.className='eyebrow';eyebrow.textContent=item.category==='Civic'?(l==='es'?'Cívico · confirme en la fuente':'Civic · check official source'):(l==='es'?'Familia · confirme en la fuente':'Family · check official source');
 const h=document.createElement(heading);h.textContent=pick(item.title,l);
 const meta=document.createElement('p');meta.className='hf39-event-meta';meta.textContent=pick(item.meta,l);
 const summary=document.createElement('p');summary.className='fine-print';summary.textContent=pick(item.summary,l);
 const actions=document.createElement('div');actions.className='r22-inline-actions';const link=document.createElement('a');link.href=item.sourceUrl;link.rel='noopener';link.target='_blank';link.textContent=pick(item.sourceLabel,l)+' ↗';actions.append(link);
 a.append(eyebrow,h,meta,summary,actions);return a;
}
function activeItems(items){const day=localDay();return items.filter(x=>String(x.end||'').slice(0,10)>=day).sort((a,b)=>String(a.start).localeCompare(String(b.start)));}
function note(container,l,checked){let n=q('[data-r1367-currentness-note]',container);if(!n){n=document.createElement('p');n.className='fine-print';n.dataset.r1367CurrentnessNote='';const head=q('.r22-section-head',container);(head||container).insertAdjacentElement('afterend',n);}n.textContent=l==='es'?`Actualidad revisada el ${checked==='2026-10-05'?'5 de octubre de 2026':checked} con fuentes oficiales de la ciudad, elecciones del condado y escuelas. Confirme los datos cambiantes en la fuente original.`:`Currentness checked ${checked==='2026-10-05'?'October 5, 2026':checked} against official City, county election and school sources. Recheck changing details at the original source.`;}
function refreshHome(data,l){const grid=q('[data-home-events]');if(!grid)return;const wrap=grid.closest('.wrap')||grid.parentElement;const items=activeItems(data.items).slice(0,3);grid.replaceChildren(...items.map(x=>card(x,l,'h3')));const empty=q('[data-home-events-empty]');if(empty)empty.hidden=items.length>0;note(wrap,l,data.checkedDate);}
function bindTodayFilters(grid){const controls=q('[data-today-filters]');const empty=q('[data-today-empty]');if(!controls)return;const fresh=controls.cloneNode(true);controls.replaceWith(fresh);let active='All';const render=()=>{let visible=0;qa('.today-card',grid).forEach(c=>{const match=active==='All'||c.dataset.eventCategory===active;c.hidden=!match;if(match)visible++});if(empty)empty.hidden=visible!==0;qa('.hf39-today-group',grid).forEach(g=>{g.hidden=qa('.today-card',g).every(c=>c.hidden)});};qa('button',fresh).forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter||'All';qa('button',fresh).forEach(x=>x.classList.toggle('active',x===b));render()}));render();}
function refreshToday(data,l){const grid=q('[data-today-grid]');if(!grid)return;const items=activeItems(data.items);const section=document.createElement('section');section.className='hf39-today-group';const h=document.createElement('h3');h.textContent=l==='es'?'Actual y próximo':'Current and upcoming';const cards=document.createElement('div');cards.className='hf39-today-grid';items.forEach(x=>cards.append(card(x,l,'h4')));section.append(h,cards);grid.replaceChildren(section);const wrap=grid.closest('.wrap')||grid.parentElement;note(wrap,l,data.checkedDate);bindTodayFilters(grid);}
function refreshStaleFreshness(l,checked){qa('p,.eyebrow').forEach(n=>{const t=(n.textContent||'').trim();if(/sources reviewed by|sources last reviewed|fuentes revisadas por última vez/i.test(t)){n.textContent=l==='es'?`Actualidad revisada el 5 de octubre de 2026 · confirme los datos cambiantes en la fuente original`:`Currentness checked October 5, 2026 · recheck changing details at the original source`;}});}
async function run(){placeholderFirewall();const meta=q('meta[name="franklin-release"]');if(meta)meta.content=RELEASE;try{const r=await fetch(DATA,{cache:'no-store'});if(!r.ok)throw Error('currentness_data_'+r.status);const data=await r.json();if(data.release!==RELEASE||!Array.isArray(data.items))throw Error('currentness_contract');if(data.items.some(x=>/^test$/i.test(pick(x.title,'en').trim())||/^test$/i.test(pick(x.title,'es').trim())))throw Error('placeholder_blocked');const l=lang();refreshStaleFreshness(l,data.checkedDate);refreshHome(data,l);refreshToday(data,l);placeholderFirewall();}catch(_){placeholderFirewall();}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run();
const mo=new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1)placeholderFirewall(n)})));if(document.documentElement)mo.observe(document.documentElement,{subtree:true,childList:true});
})();
